db.createCollection("validatedProducts", {
  validator: { $jsonSchema: {
    bsonType: "object", required: ["sku", "name", "price"],
    properties: { sku: { bsonType: "string" }, name: { bsonType: "string" }, price: { bsonType: ["int", "long", "double", "decimal"], minimum: 0 } }
  } },
  validationAction: "error"
});
